from typing import *
import heapq as hq


class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])

        # Create a list of tuples where each tuple contains the diagonal index (i + j) and the value at that position
        heap = []
        for i in range(m):
            for j in range(n):
                hq.heappush(heap, (i + j, grid[i][j]))

        # Sort the heap based on the diagonal index in descending order
        hq.heapify(heap)

        # Pop elements from the heap and place them back into the grid
        result = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                result[i][j] = hq.heappop(heap)[1]

        return result

from typing import *
import heapq as hq


class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        heap = []

        # Build min heap for each diagonal
        for i in range(m):
            for j in range(n):
                hq.heappush(heap, (-grid[i][j], i, j))

        result = [[0] * n for _ in range(m)]

        # Sort diagonals
        while heap:
            _, i, j = hq.heappop(heap)
            result[i][j] = -heapq.heappop(heap)[0]

            # Push new elements into heap if possible
            if i + 1 < m and j + 1 < n:
                hq.heappush(heap, (-grid[i+1][j+1], i+1, j+1))

        return result

from typing import *
import heapq

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Flatten the matrix into a list of tuples (diagonal index, value)
        flattened = [(i - j, val) for i in range(n) for j in range(n)]
        # Sort the list based on diagonal index and then by value
        flattened.sort()

        # Reconstruct the matrix from the sorted list
        result = [[0] * n for _ in range(n)]
        diags = {i: [] for i in range(2 * n - 1)}

        for idx, val in flattened:
            diags[idx].append(val)

        for i in range(n):
            for j in range(n):
                result[i][j] = diags[i + j].pop()

        return result
